import { useState } from 'react'
import { ArrowRight, Plus } from 'lucide-react'
import { useCatalog } from '../lib/catalog-context'
import { navigate } from '../lib/router'
import { formatNumber } from '../lib/utils'
import { SeriesCard } from '../components/SeriesCard'
import { Button } from '../components/ui'

const link =
  (to: string) =>
  (e: React.MouseEvent): void => {
    if (e.metaKey || e.ctrlKey) return
    e.preventDefault()
    navigate(to)
  }

const PAGE_SIZE = 60

const keepExploring = [
  { href: '/updates', title: 'Latest Updates', hint: 'Fresh chapters as they drop' },
  { href: '/status/ongoing', title: 'Ongoing Manhwa', hint: 'Series still updating' },
  { href: '/genres', title: 'Genre Directory', hint: 'Find your next obsession' },
]

export default function NewReleases() {
  const { series, loading } = useCatalog()
  const [count, setCount] = useState(PAGE_SIZE)

  // Newest debut first — series that started publishing most recently.
  const list = [...series].sort(
    (a, b) => +new Date(b.firstReleased) - +new Date(a.firstReleased),
  )
  const visible = list.slice(0, count)

  return (
    <main className="animate-fade-up">
      {/* Banner */}
      <div
        className="border-b border-line"
        style={{
          background:
            'linear-gradient(115deg, hsl(20 30% 14%) 0%, hsl(30 28% 26%) 100%)',
        }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <div className="eyebrow text-accent">New Releases</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">
            New Manhwa &amp; Manhua Releases
          </h1>
          <p className="mt-3 max-w-xl text-white/70">
            Fresh debuts from the catalog — series that started publishing most recently, ready to
            read from chapter one.
          </p>
          <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-white/60">
            <span>
              <strong className="text-white">{loading ? '…' : formatNumber(list.length)}</strong>{' '}
              series
            </span>
            <span>
              Showing <strong className="text-white">{formatNumber(visible.length)}</strong>
            </span>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
        {loading ? (
          <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {Array.from({ length: 10 }).map((_, i) => (
              <div key={i}>
                <div className="aspect-[3/4] animate-pulse rounded-[14px] bg-paper-3/60" />
                <div className="mt-3 h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
              </div>
            ))}
          </div>
        ) : (
          <>
            <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
              {visible.map((s) => (
                <SeriesCard key={s.id} series={s} />
              ))}
            </div>
            {count < list.length && (
              <div className="mt-12 flex justify-center">
                <Button
                  variant="outline"
                  size="lg"
                  icon={<Plus width={18} height={18} />}
                  onClick={() => setCount((c) => c + PAGE_SIZE)}
                >
                  Show more ({formatNumber(list.length - count)} left)
                </Button>
              </div>
            )}
          </>
        )}

        {/* Keep exploring */}
        <section className="mt-16">
          <div className="eyebrow mb-4 text-accent">Keep Exploring</div>
          <div className="grid gap-3 sm:grid-cols-3">
            {keepExploring.map((item) => (
              <a
                key={item.href}
                href={item.href}
                onClick={link(item.href)}
                className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
              >
                <div>
                  <div className="font-extrabold tracking-tight group-hover:text-accent">
                    {item.title}
                  </div>
                  <div className="mt-0.5 text-xs text-ink-faint">{item.hint}</div>
                </div>
                <ArrowRight
                  width={18}
                  height={18}
                  className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent"
                />
              </a>
            ))}
          </div>
        </section>
      </div>
    </main>
  )
}
